function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#051428', Frame='#4a5568', Open='#0f172a', Hint='#38bdf8';
  px(0,0,32,32,Frame); px(4,2,24,28,O); px(5,3,22,26,Open);
  px(5,3,22,1,Hint); px(14,14,4,4,Hint);

}
